section.codeblock:
from lxml import etree
DOCTYPE = ('<!DOCTYPE reference PUBLIC "-//OASIS//DTD DITA 2.0 Reference//EN" ' '"reference.dtd">')
def make_api_topic(endpoint): ref = etree.Element("reference", id=endpoint["id"]) etree.SubElement(ref, "title").text = endpoint["summary"] etree.SubElement(ref, "shortdesc").text = endpoint["description"] body = etree.SubElement(ref, "refbody")
sec = etree.SubElement(body, "section") etree.SubElement(sec, "title").text = "请求" p = etree.SubElement(sec, "p") etree.SubElement(p, "codeph").text = f'{endpoint["method"]} {endpoint["path"]}'
st = etree.SubElement(body, "simpletable", relcolwidth="1* 1* 3*") hd = etree.SubElement(st, "sthead") for h in ("参数", "类型", "说明"): etree.SubElement(hd, "stentry").text = h for param in endpoint["params"]: row = etree.SubElement(st, "strow") for v in (param["name"], param["type"], param["desc"]): etree.SubElement(row, "stentry").text = v
return etree.tostring(ref, xml_declaration=True, encoding="UTF-8", doctype=DOCTYPE, pretty_print=True)
